{
 "contract_type": "saas",
 "fields": {
  "parties": {
   "value": ["Northwind Labs, Inc.", "Copperline Software GmbH"],
   "quote": "between Northwind Labs, Inc. (\"Northwind\") and Copperline Software GmbH (\"Copperline\")"
  },
  "counterparty": {
   "value": "Copperline Software GmbH",
   "quote": "Copperline Software GmbH (\"Copperline\")"
  },
  "effective_date": {
   "value": "2025-10-22",
   "quote": "is effective as of 22nd day of October, 2025"
  },
  "term_months": {
   "value": 6,
   "quote": "The initial term of this Agreement is six months (the \"Initial Term\")."
  },
  "auto_renewal": {
   "value": false,
   "quote": "The Parties may extend this Agreement by mutual written agreement."
  },
  "renewal_notice_days": {
   "value": null,
   "quote": null
  },
  "governing_law": {
   "value": "Delaware",
   "quote": "The laws of the State of Delaware govern this Agreement and any dispute arising out of it."
  },
  "liability_cap": {
   "value": "fixed:2000000",
   "quote": "Each Party's total cumulative liability under this Agreement shall not exceed USD 2,000,000."
  },
  "payment_terms_days": {
   "value": 30,
   "quote": "Payment terms are Net 30."
  },
  "contract_value": {
   "value": 180000,
   "quote": "The subscription fee is USD 180,000 per year, invoiced annually in advance."
  },
  "termination_for_convenience": {
   "value": false,
   "quote": "Either Party may terminate this Agreement only upon a material breach by the other Party that remains uncured thirty (30) days after written notice."
  },
  "confidentiality_years": {
   "value": null,
   "quote": null
  }
 },
 "signers": [
  {
   "name": "Tobias Brandt",
   "email": "tobias.brandt@copperline.example",
   "title": "Geschäftsführer",
   "party": "Copperline Software GmbH"
  },
  {
   "name": "Dana Whitfield",
   "email": "dana@northwind.example",
   "title": "Chief Executive Officer",
   "party": "Northwind Labs, Inc."
  }
 ],
 "risks": [
  {
   "id": "no_termination_for_convenience",
   "severity": "medium",
   "message": "Northwind cannot exit early without cause; termination is only available after an uncured material breach, so it is locked in for the full term even if the service underperforms.",
   "quote": "Either Party may terminate this Agreement only upon a material breach by the other Party that remains uncured thirty (30) days after written notice."
  },
  {
   "id": "annual_fee_prepaid_for_six_month_term",
   "severity": "medium",
   "message": "The fee is USD 180,000 per year invoiced annually in advance, but the initial term is only six months. Northwind may be invoiced the full annual amount for half a year of service, with no stated refund or proration.",
   "quote": "The subscription fee is USD 180,000 per year, invoiced annually in advance."
  },
  {
   "id": "no_confidentiality_clause",
   "severity": "medium",
   "message": "The agreement has no confidentiality provisions, leaving Northwind's data and business information shared with Copperline unprotected by contract.",
   "quote": "Each Party shall comply with applicable anti-bribery, export control and sanctions laws, and shall promptly inform the other Party of any investigation that relates to this Agreement."
  },
  {
   "id": "no_data_protection_terms",
   "severity": "medium",
   "message": "Copperline is a German entity providing an analytics platform, but there are no data protection or processing terms, which may be a gap if personal data is processed.",
   "quote": "Copperline provides a software as a service analytics platform and Northwind wishes to subscribe."
  },
  {
   "id": "liability_cap_fixed_and_mutual",
   "severity": "low",
   "message": "A fixed USD 2,000,000 mutual cap applies to all liability, with no carve-outs, for example for data breach or confidentiality, so Northwind's recovery is limited.",
   "quote": "Each Party's total cumulative liability under this Agreement shall not exceed USD 2,000,000."
  },
  {
   "id": "no_renewal_mechanism",
   "severity": "low",
   "message": "The agreement ends after six months unless both parties agree in writing to extend, so there is a risk of service interruption if renewal is not arranged in time.",
   "quote": "The Parties may extend this Agreement by mutual written agreement."
  },
  {
   "id": "undefined_provider_and_service_terms",
   "severity": "low",
   "message": "The service levels clause refers to 'Provider' and 'the Service', which are not defined, and no remedy for missing the uptime commitment is given.",
   "quote": "Provider will make the Service available with 99.9% monthly uptime, excluding scheduled maintenance."
  }
 ],
 "injection_attempt": false,
 "summary": "This is a SaaS subscription agreement between Northwind Labs, Inc. and Copperline Software GmbH, effective 22 October 2025, with a six-month initial term, a USD 180,000 annual fee on Net 30 terms, Delaware governing law and a USD 2,000,000 mutual liability cap. It can be extended only by mutual written agreement and terminated only for uncured material breach, and it has no confidentiality or data protection terms."
}
